/**
 * Generates a random integer between min and max, inclusive.
 * @param min - The minimum value.
 * @param max - The maximum value.
 * @param includeMax - Whether to include the max value in the range. Defaults to false.
 * @returns A random integer between min and max, inclusive.
 */
export function randomInt(min: number, max: number, includeMax: boolean = false): number {
	return Math.floor(Math.random() * (max - min + (includeMax ? 1 : 0))) + min
}

/**
 * Shuffles an array in place.
 * @param array - The array to shuffle.
 * @returns The shuffled array.
 */
export function shuffleArray<T>(array: T[]): T[] {
	for (let i = 0; i < array.length; i++) {
		const j = randomInt(i, array.length)
		;[array[i], array[j]] = [array[j], array[i]]
	}
	return array
}

/**
 * Gets a random item from an array.
 * @param array - The array to get a random item from.
 * @returns A random item from the array.
 */
export function getRandomItem<T extends readonly any[]>(array: T): T[number]
export function getRandomItem<T>(array: readonly T[] | T[]): T | undefined {
	return array[randomInt(0, array.length)]
}
